CREATE TABLE tenant(tenant_id varchar(150) PRIMARY KEY,status varchar(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE subject(subject_id varchar(150) PRIMARY KEY,login_name varchar(150) UNIQUE NOT NULL,password_hash text NOT NULL,status varchar(20) NOT NULL DEFAULT 'ACTIVE');
CREATE TABLE membership(tenant_id varchar(150) REFERENCES tenant ON DELETE CASCADE,subject_id varchar(150) REFERENCES subject ON DELETE CASCADE,role varchar(40) NOT NULL CHECK(role IN ('employee','knowledge-maintainer')),status varchar(20) NOT NULL DEFAULT 'ACTIVE',version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,subject_id));
CREATE TABLE authorization_epoch(tenant_id varchar(150),subject_id varchar(150),version bigint NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,subject_id),FOREIGN KEY(tenant_id,subject_id) REFERENCES membership ON DELETE CASCADE);
CREATE TABLE auth_session(session_id varchar(80) PRIMARY KEY,credential_hash char(64) UNIQUE NOT NULL,subject_id varchar(150) NOT NULL,tenant_id varchar(150) NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,version bigint NOT NULL DEFAULT 1,csrf_hash char(64) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,subject_id) REFERENCES membership ON DELETE CASCADE);
CREATE INDEX session_subject ON auth_session(subject_id,tenant_id);
CREATE TABLE resource_owner(resource_type varchar(80),resource_id varchar(150),tenant_id varchar(150) NOT NULL,subject_id varchar(150) NOT NULL,state varchar(20) NOT NULL DEFAULT 'ACTIVE',version bigint NOT NULL DEFAULT 1,legacy_import_id varchar(150),PRIMARY KEY(resource_type,resource_id),FOREIGN KEY(tenant_id,subject_id) REFERENCES membership ON DELETE CASCADE);
CREATE TABLE authorization_audit(decision_id varchar(80) PRIMARY KEY,run_id varchar(150),phase varchar(40) NOT NULL,tenant_id varchar(150) NOT NULL,subject_id varchar(150) NOT NULL,session_id varchar(80) NOT NULL,action varchar(80) NOT NULL,resource_type varchar(80),resource_id varchar(150),version varchar(150) NOT NULL,allowed boolean NOT NULL,code varchar(60) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_call_ticket(ticket_hash char(64) PRIMARY KEY,audience varchar(80) NOT NULL,action varchar(80) NOT NULL,actor_session_id varchar(80) NOT NULL REFERENCES auth_session ON DELETE CASCADE,authentication_version bigint NOT NULL,resource_type varchar(80),resource_id varchar(150),request_sha256 char(64) NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz);
